export function fmtMoney(v) {
  const n = parseFloat((v || "").toString().replace(/,/g, "")) || 0;
  return n > 0 ? n.toLocaleString() : null;
}

// calcVatBreakdown / calcTotal live in src/logic/money.js
export function makeSignatureTransparent(base64src) {
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => {
      // Scale down so huge phone photos don't bloat KV storage
      const maxDim = 1400;
      const scale = Math.min(1, maxDim / Math.max(img.width, img.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.round(img.width * scale);
      canvas.height = Math.round(img.height * scale);
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      const id = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const d = id.data;

      // Collect all pixel luminances to find the actual paper brightness
      // (accounts for dim lighting, warm/cream paper, shadows)
      const lums = new Float32Array(d.length / 4);
      for (let i = 0, p = 0; i < d.length; i += 4, p++) {
        lums[p] = d[i] * 0.299 + d[i+1] * 0.587 + d[i+2] * 0.114;
      }
      const sorted = Float32Array.from(lums).sort();
      // 95th-percentile = the brightest area = paper white (not blown-out specular)
      const paperLum = sorted[Math.floor(sorted.length * 0.95)] || 230;
      // Ink cutoff: pixels brighter than 78% of paper → background
      const cutoff = paperLum * 0.78;

      for (let i = 0, p = 0; i < d.length; i += 4, p++) {
        const l = lums[p];
        if (l >= cutoff) {
          d[i+3] = 0;
        } else {
          // Keep original ink color, just set alpha by darkness
          const t = Math.pow((cutoff - l) / cutoff, 0.5);
          d[i+3] = Math.min(255, Math.round(t * 255));
        }
      }

      ctx.putImageData(id, 0, 0);
      resolve(canvas.toDataURL("image/png"));
    };
    img.onerror = () => resolve(base64src);
    img.src = base64src;
  });
}

// Revision letter lives in src/logic/docNumber.js (fmtDocNo).
export const fmtInvoiceNo = fmtDocNo;

export const esc = (s) => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

export const LOGO_B64 = "data:image/png;base64,";

export function buildInvoiceHTML({ invoice, employee, profileInfo, promptPayQR, idCard, signature, productionCompanies, companyName, autoPrint = false, headerLogo = null, headerLogoPos = null, watermarkLogo = null, watermarkLogoPos = null }) {
  // Bill To prints from the snapshot taken at save time (P2-9); legacy documents fall back to the live list.
  const billTo = resolveBillTo(invoice, productionCompanies || []);
  const headerText = invoice.invoiceHeader != null ? invoice.invoiceHeader : (companyName || "GEAR DESK");
  const isAdminInvoice = employee?.id === "admin";
  const embed = embedFlags(invoice); // ID card opt-in per document, signature/bank optional (P0-7)
  const title = docTitle(invoice.docType);
  const isVoid = invoice.status === "Void";

  const items = printableItems(invoice); // rate-empty rows never print (P2-4)
  const { subtotal, vatAmount, total, whtRate, whtAmount, netPayable } = docTotals(invoice);

  const fmtD = (d, opts) => new Date(d + "T00:00:00").toLocaleDateString("en-GB", opts);
  const dateStr = (invoice.shootDates || []).map(d => fmtD(d, { day: "numeric", month: "short" })).join(", ");
  const invDate = new Date(invoice.createdAt).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
  const statusColor = invoice.status === "Paid" ? "#065f46" : "#92400e";
  const statusBg = invoice.status === "Paid" ? "#d1fae5" : "#fef3c7";
  const money = n => "฿" + Math.round(n).toLocaleString();
  const money2 = n => "฿" + n.toLocaleString("en", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const hasMixedVat = invoice.vatEnabled && items.some(it => it.vat === false) && items.some(it => it.vat !== false);
  const itemRows = items.map(it => {
    const qty = parseFloat(it.qty) || 0;
    const rate = parseFloat((it.rate || "").toString().replace(/,/g, "")) || 0;
    const lineTotal = qty * rate;
    const noVatMark = (invoice.vatEnabled && hasMixedVat && it.vat === false) ? `<sup style="color:#888">*</sup>` : "";
    return `<tr>
      <td>${esc(it.description)}${noVatMark}</td>
      <td class="num">${qty % 1 === 0 ? qty : qty.toFixed(2)}</td>
      <td class="num">฿${rate.toLocaleString()}</td>
      <td class="num"><strong>฿${lineTotal.toLocaleString()}</strong></td>
    </tr>`;
  }).join("");

  const fromName = profileInfo?.firstName ? `${profileInfo.firstName} ${profileInfo.lastName || ""}`.trim() : (employee?.name || "");
  const fromTaxId = (profileInfo?.taxId || "").trim();
  const showBank = embed.bank && (profileInfo?.bankName || profileInfo?.bankAccount || profileInfo?.accountName);
  const showQr = embed.bank && promptPayQR;
  const showId = embed.idCard && idCard;
  const showSig = embed.signature && signature;
  const dueDate = invoice.dueDate || "";
  const termsLabel = dueDate ? fmtD(dueDate, { day: "numeric", month: "long", year: "numeric" }) : (invoice.termsDays === 0 || invoice.termsDays === "0" ? "Due on receipt" : "");
  const paidLine = invoice.docType === "receipt" && invoice.paidDate ? `<div style="font-size:10px;color:#555;margin-top:2px">วันที่รับเงิน / Paid: ${fmtD(invoice.paidDate, { day: "numeric", month: "long", year: "numeric" })}</div>` : "";

  const totalsFoot = (() => {
    const rows = [];
    const muted = `style="font-size:10px;color:#888;font-weight:400;border-top:1px solid #ddd"`;
    const mutedNum = `class="num" style="font-size:10px;color:#888;border-top:1px solid #ddd"`;
    const subLabel = invoice.vatType === "inclusive" ? "รวมก่อนภาษี / Subtotal (excl. VAT)" : "รวม / Subtotal";
    const vatLabel = invoice.vatType === "inclusive" ? "ภาษีมูลค่าเพิ่ม 7% / VAT 7% (incl.)" : "ภาษีมูลค่าเพิ่ม 7% / VAT 7%";
    if (invoice.vatEnabled) {
      rows.push(`<tr><td colspan="3" ${muted}>${subLabel}</td><td ${mutedNum}>${money2(subtotal)}</td></tr>`);
      rows.push(`<tr><td colspan="3" style="font-size:10px;color:#888;font-weight:400">${vatLabel}</td><td class="num" style="font-size:10px;color:#888">${money2(vatAmount)}</td></tr>`);
    }
    const totalLabel = invoice.vatEnabled ? "ยอดรวม / TOTAL AMOUNT (incl. VAT)" : "ยอดรวม / TOTAL AMOUNT";
    rows.push(`<tr class="total-row"><td colspan="3">${totalLabel}</td><td class="num">${money(total)}</td></tr>`);
    if (whtRate > 0) {
      rows.push(`<tr><td colspan="3" style="font-size:10px;color:#555;font-weight:400;border-bottom:none">หัก ณ ที่จ่าย / Withholding tax ${whtRate}%</td><td class="num" style="font-size:10px;color:#555;border-bottom:none">− ${money2(whtAmount)}</td></tr>`);
      rows.push(`<tr class="total-row"><td colspan="3" style="border-top:1px solid #111;font-size:11px">ยอดสุทธิที่ต้องชำระ / NET PAYABLE</td><td class="num" style="border-top:1px solid #111;font-size:11px">${money(netPayable)}</td></tr>`);
    }
    return rows.join("");
  })();

  const html = `<!DOCTYPE html><html><head><title>${esc(invoice.invoiceNo)}</title><meta charset="utf-8"><meta name="format-detection" content="telephone=no,email=no,address=no,date=no"><meta name="robots" content="noindex"><style>
    @page{size:A4 portrait;margin:0}
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:'Helvetica Neue',Arial,sans-serif;color:#111;font-size:10.5px;background:#fff}
    .page{position:relative;width:210mm;min-height:297mm;padding:10mm;overflow:hidden}
    .hdr{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px}
    .divider{border-top:2px solid #111;margin-bottom:10px}
    .grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:8px}
    .job-box{background:#f7f7f7;border-radius:5px;padding:7px 12px;margin-bottom:8px;border-left:3px solid #111}
    .lbl{font-size:8px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#888;margin-bottom:3px}
    table{width:100%;border-collapse:collapse;margin-bottom:8px}
    th{text-align:left;font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#888;padding:4px 7px;border-bottom:1.5px solid #ccc;background:#fafafa}
    td{padding:5px 7px;border-bottom:1px solid #f0f0f0;font-size:10.5px}
    .num{text-align:right;width:76px}
    .total-row td{border-top:2px solid #111;border-bottom:none;font-weight:800;font-size:12px;padding-top:6px}
    .bottom-box{border:1.5px solid #ddd;border-radius:7px;padding:12px 16px;margin-top:10px;display:flex;gap:18px;align-items:center;justify-content:center;flex-wrap:wrap}
    .id-wrap{width:160px;flex-shrink:0}
    .id-img{width:100%;height:auto;max-height:106px;border-radius:5px;display:block;border:1px solid #ddd}
    .sig-col{flex-shrink:0;display:flex;flex-direction:column;align-items:center}
    .sig-img{width:160px;height:auto;max-height:80px;opacity:.95}
    .bank{font-size:10px;color:#444;line-height:1.7;text-align:center;pointer-events:none}
    .void{position:absolute;top:40%;left:50%;transform:translate(-50%,-50%) rotate(-24deg);font-size:64px;font-weight:900;color:rgba(197,48,48,0.22);letter-spacing:.2em;border:6px solid rgba(197,48,48,0.22);padding:6px 24px;border-radius:12px;pointer-events:none;z-index:2}
    @media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
  </style></head><body>
  <div class="page">
  ${watermarkLogo && watermarkLogoPos ? `<img src="${watermarkLogo}" style="position:absolute;left:${watermarkLogoPos.x}mm;top:${watermarkLogoPos.y}mm;width:${watermarkLogoPos.width || 120}mm;opacity:${watermarkLogoPos.opacity ?? 0.08};pointer-events:none;z-index:0" />` : ""}
  ${headerLogo && headerLogoPos ? `<img src="${headerLogo}" style="position:absolute;left:${headerLogoPos.x}mm;top:${headerLogoPos.y}mm;width:${headerLogoPos.width || 40}mm;opacity:${headerLogoPos.opacity ?? 1};pointer-events:none;z-index:0" />` : ""}
  ${isVoid ? `<div class="void">VOID</div>` : ""}
  <div style="position:relative;z-index:1">
  <div class="hdr">
    <div>
      <div style="font-size:20px;font-weight:800;letter-spacing:.01em">${esc(headerText)}</div>
    </div>
    <div style="text-align:right">
      <div style="font-size:15px;font-weight:800;letter-spacing:.02em">${title.th}</div>
      <div style="font-size:22px;font-weight:900;letter-spacing:.04em;line-height:1.1">${title.en}</div>
      <div style="font-size:11px;color:#555;margin-top:3px">#${esc(fmtInvoiceNo(invoice))}</div>
      <div style="font-size:10px;color:#888;margin-top:2px">${invDate}</div>
      ${termsLabel && invoice.docType !== "receipt" ? `<div style="font-size:10px;color:#555;margin-top:2px">ครบกำหนด / Due: ${esc(termsLabel)}</div>` : ""}
      ${paidLine}
      ${invoice.status === "Paid" ? `<div style="margin-top:6px;display:inline-block;padding:2px 10px;border-radius:20px;font-size:9.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;background:${statusBg};color:${statusColor}">PAID</div>` : ""}
      ${isVoid ? `<div style="margin-top:6px;display:inline-block;padding:2px 10px;border-radius:20px;font-size:9.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;background:#fee2e2;color:#991b1b">VOID${invoice.voidReason ? `: ${esc(invoice.voidReason)}` : ""}</div>` : ""}
    </div>
  </div>
  <div class="divider"></div>
  <div class="grid2">
    <div>
      <div class="lbl">ลูกค้า / Bill To</div>
      <div style="font-weight:700;font-size:13px">${esc(billTo.name || "—")}</div>
      ${billTo.address ? `<div style="font-size:10.5px;color:#555;white-space:pre-wrap;margin-top:3px;line-height:1.5">${esc(billTo.address)}</div>` : ""}
      ${billTo.taxId ? `<div style="font-size:10px;color:#555;margin-top:3px">เลขประจำตัวผู้เสียภาษี / Tax ID: ${esc(billTo.taxId)}${billTo.branch ? ` &nbsp;·&nbsp; สาขา / Branch: ${esc(billTo.branch)}` : ""}</div>` : (billTo.branch ? `<div style="font-size:10px;color:#555;margin-top:3px">สาขา / Branch: ${esc(billTo.branch)}</div>` : "")}
    </div>
    <div>
      <div class="lbl">ผู้ออกเอกสาร / From</div>
      <div style="font-weight:700;font-size:13px">${esc(fromName)}</div>
      ${profileInfo?.legalAddress ? `<div style="font-size:10.5px;color:#555;white-space:pre-wrap;margin-top:3px;line-height:1.5">${esc(profileInfo.legalAddress)}</div>` : ""}
      ${fromTaxId ? `<div style="font-size:10px;color:#555;margin-top:3px">เลขประจำตัวผู้เสียภาษี / Tax ID: ${esc(fromTaxId)}</div>` : ""}
      ${profileInfo?.phone ? `<div style="font-size:10.5px;color:#555;margin-top:3px">Phone No.: ${esc(profileInfo.phone)}</div>` : ""}
      ${profileInfo?.email ? `<div style="font-size:10.5px;color:#555;margin-top:2px">Email: ${esc(profileInfo.email)}</div>` : ""}
    </div>
  </div>
  <div class="job-box">
    <div style="font-weight:700;font-size:13px;margin-bottom:3px">${esc(invoice.jobName)}</div>
    ${(invoice.position || dateStr) ? `<div style="font-size:11px;color:#555">${invoice.position ? `Position: <strong>${esc(invoice.position)}</strong>` : ""}${invoice.position && dateStr ? " &nbsp;|&nbsp; " : ""}${dateStr ? `Dates: ${dateStr}` : ""}</div>` : ""}
  </div>
  ${invoice.callWrap && Object.keys(invoice.callWrap).some(d => invoice.callWrap[d]?.call || invoice.callWrap[d]?.wrap) ? `
  <table style="margin-bottom:8px;width:auto;min-width:260px">
    <thead><tr><th>Date</th><th>Call Time</th><th>Wrap Time</th></tr></thead>
    <tbody>${Object.keys(invoice.callWrap).sort().map(d => {
      const cw = invoice.callWrap[d];
      if (!cw?.call && !cw?.wrap) return "";
      const label = fmtD(d, { day: "numeric", month: "short" });
      return `<tr><td>${label}</td><td>${fmtClock(cw.call)}</td><td>${fmtClock(cw.wrap)}</td></tr>`;
    }).join("")}</tbody>
  </table>` : ""}
  <table>
    <thead><tr><th>รายการ / Description</th><th class="num">Qty</th><th class="num">Rate</th><th class="num">Total</th></tr></thead>
    <tbody>${itemRows}</tbody>
    <tfoot>${totalsFoot}</tfoot>
  </table>
  ${hasMixedVat ? `<p style="font-size:8.5px;color:#999;margin:2px 0 8px"><sup>*</sup> Non 7% VAT</p>` : ""}
  ${whtRate > 0 ? `<p style="font-size:8.5px;color:#777;margin:2px 0 8px">ผู้จ่ายเงินหักภาษี ณ ที่จ่าย ${whtRate}% และออกหนังสือรับรอง (50 ทวิ) ให้ผู้รับเงิน / Payer withholds ${whtRate}% and issues a withholding-tax certificate.</p>` : ""}
  ${(showQr || showBank || showId || showSig) ? `
  <div class="bottom-box">
    ${(showQr || showBank) ? `<div style="text-align:center;flex-shrink:0">
      <div class="lbl" style="margin-bottom:6px">${showQr ? "PromptPay / QR Payment" : "ชำระเงิน / Payment"}</div>
      ${showQr ? `<img src="${promptPayQR}" style="width:208px;height:208px;object-fit:contain;border:1px solid #ddd;border-radius:6px;background:#fff"/>` : ""}
      ${showBank ? `<div class="bank" style="margin-top:6px">
        ${profileInfo.bankName ? `<div style="font-weight:700">${esc(profileInfo.bankName)}</div>` : ""}
        ${profileInfo.accountName ? `<div>${esc(profileInfo.accountName)}</div>` : ""}
        ${profileInfo.bankAccount ? `<div>${esc(profileInfo.bankAccount)}</div>` : ""}
      </div>` : ""}
    </div>` : ""}
    ${showId ? `<div class="id-wrap">
      <div class="lbl" style="margin-bottom:6px">สำเนาบัตรประชาชน / ID Card</div>
      <img class="id-img" src="${idCard}" />
      <div style="font-size:8.5px;color:#666;text-align:center;margin-top:4px">สำเนาถูกต้อง</div>
    </div>` : ""}
    ${showSig ? `<div class="sig-col">
      <div style="font-size:8.5px;color:#888;text-align:center;line-height:1.6;margin-bottom:8px;max-width:180px">
        ข้อมูลและสำเนาถูกต้อง<br>ใช้สำหรับงาน <strong>${esc(invoice.jobName || "—")}</strong><br>ของ <strong>${esc(billTo.name || "—")}</strong>
      </div>
      <img class="sig-img" src="${signature}" />
    </div>` : ""}
  </div>` : ""}
  </div>
  ${(isAdminInvoice ? invoice.showWatermark : true) ? `<img src="${LOGO_B64}" style="position:absolute;bottom:15mm;right:10mm;width:31.5mm;opacity:0.12;pointer-events:none;z-index:0" />` : ""}
  </div>
  ${autoPrint ? `<script>window.onload=()=>{setTimeout(()=>{window.print();window.onafterprint=()=>window.close();},600);}<\/script>` : ""}
  </body></html>`;
  return html;
}

export function printInvoice({ invoice, employee, profileInfo, promptPayQR, idCard, signature, productionCompanies, companyName, print: doPrint = true }) {
  const html = buildInvoiceHTML({ invoice, employee, profileInfo, promptPayQR, idCard, signature, productionCompanies, companyName, autoPrint: doPrint });
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  window.open(url, "_blank");
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

export const DEFAULT_ITEMS = [
  { id: "d1", description: "Labor (12hr)", qty: 1, rate: "", vat: true },
  { id: "d2", description: "Overtime", qty: 1, rate: "", vat: true },
  { id: "d3", description: "Travel Day Fee", qty: 1, rate: "", vat: true },
];

export function migrateItems(inv) {
  if (inv?.items) return inv.items.map(it => ({ vat: true, ...it }));
  const items = [];
  const add = (desc, val) => { if (parseFloat(val) > 0) items.push({ id: "m" + desc, description: desc, qty: 1, rate: val, vat: true }); };
  add("Labor (12hr)", inv?.laborFee); add("Overtime", inv?.overtime);
  add("Travel Day Fee", inv?.travelFee); add("Per Diem", inv?.perDiem);
  return items.length ? items : JSON.parse(JSON.stringify(DEFAULT_ITEMS));
}

